{
  "schema_version": "spine_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "title": "Welcome to the RNG-Hellscape",
      "goal": "Introduce Artie and his broken 'Crit-Only' status in a high-stakes environment.",
      "chapter_role": "hook",
      "stakes_shift": "Artie transitions from a mundane office drone to a level 1 glitch in a lethal game world.",
      "bridge": {
        "from_prev": "N/A",
        "to_next": "Artie must find a way to survive his first night with zero defensive stats and a target on his back."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "rush",
        "expected_scene_count": 8
      }
    },
    {
      "chapter_id": 2,
      "title": "The Glass Cannon's Guide to Not Dying",
      "goal": "Secure gear that compensates for a 1 HP build through tactical exploitation of System bugs.",
      "chapter_role": "setup",
      "stakes_shift": "Survival shifts from pure luck to the active tactical exploitation of the System's mechanical flaws.",
      "bridge": {
        "from_prev": "Artie is a marked man in Oakhaven with no protection.",
        "to_next": "Artie enters the Low-Level Crypts to put his new evasion-focused theory into practice."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 9
      }
    },
    {
      "chapter_id": 3,
      "title": "Math-Boss vs. The Glitch",
      "goal": "Defeat the Floor Guardian and secure a major loot drop to validate the 'Crit' build.",
      "chapter_role": "pressure",
      "stakes_shift": "Artie moves from a struggling survivor to a high-level 'Anomaly' with the power to break boss mechanics.",
      "bridge": {
        "from_prev": "The Bone Golem stands between Artie and his first major progression milestone.",
        "to_next": "Artie leaves the crypts with legendary loot and a growing reputation that attracts dangerous rivals."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "steady",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 4,
      "title": "The Capital of Crits",
      "goal": "Navigate the social and political dangers of the capital while seeking a way to stabilize his build.",
      "chapter_role": "investigation",
      "stakes_shift": "The conflict escalates from physical survival to avoiding detection by the 'System Police' and religious zealots.",
      "bridge": {
        "from_prev": "Artie is a fugitive from Vane's ego, seeking refuge in the heart of the System's culture.",
        "to_next": "Artie enters the Grand Arena, trading his anonymity for a chance at a game-changing artifact."
      },
      "pacing": {
        "intensity": 2,
        "tempo": "slow_burn",
        "expected_scene_count": 8
      }
    },
    {
      "chapter_id": 5,
      "title": "The Tournament of Tiers",
      "goal": "Win the arena brackets without taking damage to claim the Shield of Infinite Health.",
      "chapter_role": "trial",
      "stakes_shift": "Artie becomes a public icon, forcing the System to actively intervene and attempt to 'balance' his existence.",
      "bridge": {
        "from_prev": "Artie is the underdog entrant in a tournament designed for high-HP warriors.",
        "to_next": "Artie reaches the finals, facing a rigged match against his primary rival, Vane."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "steady",
        "expected_scene_count": 11
      }
    },
    {
      "chapter_id": 6,
      "title": "The Final Roll",
      "goal": "Defeat Vane in the finals and survive the System's direct attempt to delete the 'Anomaly'.",
      "chapter_role": "climax",
      "stakes_shift": "The stakes escalate from personal survival to the stability of the entire game world's source code.",
      "bridge": {
        "from_prev": "Artie enters the ring against a 'Whale' player backed by System-level cheats.",
        "to_next": "The System crashes under the weight of Artie's crits, leaving him in the wreckage of a broken reality."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "rush",
        "expected_scene_count": 12
      }
    },
    {
      "chapter_id": 7,
      "title": "Rebooting for the Sequel",
      "goal": "Establish a new status quo in the 'Safe Mode' world and identify the path to the Server Room.",
      "chapter_role": "aftermath",
      "stakes_shift": "Artie evolves from a local glitch into the most wanted entity in the multiverse.",
      "bridge": {
        "from_prev": "Artie and Fizz are stranded in the Null-Zone after the world-shattering climax.",
        "to_next": "Artie begins the long-term quest to reach the Source Code and delete the System Administrator."
      },
      "pacing": {
        "intensity": 2,
        "tempo": "slow_burn",
        "expected_scene_count": 8
      }
    }
  ]
}

